function formatVersionBadge(version: string, fallback: string): string {
  const trimmed = version.trim()
  if (!trimmed) {
    return fallback
  }
  if (trimmed === 'dev' || trimmed.startsWith('dev-') || trimmed.startsWith('v')) {
    return trimmed
  }
  return `v${trimmed}`
}

