function traceQueryKey(query: TraceQueryState): string {
	return [query.page, query.pageSize, query.aliases.join('\u0000'), query.failoverCounts.join(','), query.statusCodes.join(',')].join('|')
}

function resolveDraftAliasProtocol(
	aliasName: string,
	aliasForm: AliasFormState,
	selectedAlias: AliasView | null,
	aliases: AliasView[],
	preferDraftProtocol: boolean,
): ProviderProtocol {
	const trimmedAlias = aliasName.trim()
	const draftAlias = aliasForm.alias.trim()
	const storedAlias = aliases.find((alias) => alias.alias === trimmedAlias) || null
	if (preferDraftProtocol && (!trimmedAlias || trimmedAlias === draftAlias || !storedAlias)) {
		return aliasForm.protocol
	}
	return resolveAliasProtocol(storedAlias || selectedAlias)
}

function providerDefaultGroup(provider: ProviderView | null | undefined): ProviderGroupView | null {
	return provider?.groups?.find((group) => group.id === 'default') || null
}

function providerAllModels(provider: ProviderView): string[] {
	return Array.from(new Set((provider.groups || []).flatMap((group) => group.models || [])))
}

function aliasNameMatchesProviderCatalog(aliasName: string, protocol: ProviderProtocol, providers: ProviderView[]): boolean {
  const name = aliasName.trim()
  if (!name) {
    return false
  }
  return providers.some((provider) =>
    (provider.groups || []).some((group) => group.protocol === protocol && (group.models || []).includes(name)),
  )
}

function selectedTraceModel(providerId: string, providers: ProviderView[], groupId = 'default'): string[] {
	return providers.find((provider) => provider.id === providerId)?.groups?.find((group) => group.id === groupId)?.models || []
}

function providerDisplayLabel(providerId: string, providers: ProviderView[]): string {
  const id = providerId.trim()
  if (!id) {
    return ''
  }
  const provider = providers.find((item) => item.id === id)
  return provider?.name?.trim() || id
}

function providerDisplayTitle(providerId: string | undefined, providers: ProviderView[]): string | undefined {
  const id = (providerId || '').trim()
  if (!id) {
    return undefined
  }
  const label = providerDisplayLabel(id, providers)
  return label && label !== id ? `${label} (${id})` : id
}

function providerModelDisplay(providerId: string | undefined, model: string | undefined, providers: ProviderView[]): string {
  const provider = providerDisplayLabel(providerId || '', providers)
  const modelName = (model || '').trim()
  if (provider && modelName) {
    return `${provider}/${modelName}`
  }
  return provider || modelName || '-'
}

function aliasTargetDisplay(target: AliasTargetView, autoAlias: boolean, providers: ProviderView[]): { label: string; title: string } {
  const group = target.group || 'default'
  const title = `${target.provider}/${group}/${target.model}`
  const provider = providerDisplayLabel(target.provider, providers)
  if (autoAlias) {
    return { label: provider, title }
  }
  return { label: providerModelDisplay(target.provider, target.model, providers), title }
}

function localDateTimeInputValue(value: string): string {
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) {
    return ''
  }
  const pad = (part: number) => String(part).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`
}

function toggleString(list: string[], value: string, checked: boolean): string[] {
  if (checked) {
    return list.includes(value) ? list : [...list, value]
  }
  return list.filter((item) => item !== value)
}

function rewriteRuleGroupSelectorKey(selector: { provider: string; group: string }): string {
  return `${selector.provider}/${selector.group || 'default'}`
}

function rewriteRuleGroupOptions(alias: AliasView | null, providers: ProviderView[]): RewriteRuleGroupOption[] {
  if (!alias) {
    return []
  }
  const seen = new Set<string>()
  const options: RewriteRuleGroupOption[] = []
  for (const target of alias.targets) {
    const group = target.group || 'default'
    const id = rewriteRuleGroupSelectorKey({ provider: target.provider, group })
    if (seen.has(id)) {
      continue
    }
    seen.add(id)
    options.push({
      id,
      provider: target.provider,
      group,
      label: `${providerDisplayLabel(target.provider, providers)} / ${group}`,
    })
  }
  return options
}

function rewriteRuleEffectiveGroupIds(selectedGroups: RewriteRuleGroupSelection, optionIds: string[]): string[] {
  if (selectedGroups === null) {
    return optionIds
  }
  const selectedIds = new Set(selectedGroups.map(rewriteRuleGroupSelectorKey))
  return optionIds.filter((optionId) => selectedIds.has(optionId))
}

function rewriteRuleToggleGroup(
  selectedGroups: RewriteRuleGroupSelection,
  options: RewriteRuleGroupOption[],
  optionId: string,
  selected: boolean,
): ProviderGroupSelectorInput[] {
  const optionIds = options.map((option) => option.id)
  const effectiveIds = rewriteRuleEffectiveGroupIds(selectedGroups, optionIds)
  const nextIds = selected
    ? [...effectiveIds, optionId]
    : effectiveIds.filter((item) => item !== optionId)
  const selectedIdSet = new Set(optionIds.filter((item) => nextIds.includes(item)))
  return options
    .filter((option) => selectedIdSet.has(option.id))
    .map((option) => ({ provider: option.provider, group: option.group }))
}

function rewriteRuleGroupsForInput(
  selectedGroups: RewriteRuleGroupSelection,
  options: RewriteRuleGroupOption[],
): ProviderGroupSelectorInput[] | undefined {
  // null = explicit wildcard → omit/empty selector. Precise full selection keeps group IDs.
  if (selectedGroups === null) {
    return undefined
  }
  const optionIds = options.map((option) => option.id)
  const scopedIds = rewriteRuleEffectiveGroupIds(selectedGroups, optionIds)
  if (scopedIds.length === 0) {
    return []
  }
  const selectedIdSet = new Set(scopedIds)
  return options
    .filter((option) => selectedIdSet.has(option.id))
    .map((option) => ({ provider: option.provider, group: option.group }))
}

function rewriteRuleGroupScopeText(
  selectors: ProviderGroupSelectorView[] | undefined,
  alias: AliasView | null,
  providers: ProviderView[],
): string {
  const selectedSelectors = selectors || []
  if (selectedSelectors.length === 0) {
    return i18n.t('rewriteRules.providerScopeAll')
  }
  const options = rewriteRuleGroupOptions(alias, providers)
  const optionIds = options.map((option) => option.id)
  const selectedIds = selectedSelectors.map(rewriteRuleGroupSelectorKey)
  const allSelected = optionIds.length > 0
    && selectedIds.length === optionIds.length
    && optionIds.every((optionId) => selectedIds.includes(optionId))
  if (allSelected) {
    return i18n.t('rewriteRules.providerScopeAll')
  }
  const labels = selectedSelectors.map((selector) => {
    const group = selector.group || 'default'
    return `${providerDisplayLabel(selector.provider, providers)} / ${group}`
  })
  return i18n.t('rewriteRules.providerScopeSome', { providers: labels.join(', ') })
}

function tracePageCount(total: number, pageSize: number): number {
	return Math.max(1, Math.ceil(total / pageSize))
}

function preserveTracePage(currentPage: number, currentPageSize: number, nextPageSize: number, total: number): number {
	const safeCurrentPage = Math.max(1, currentPage)
	const safeCurrentPageSize = Math.max(1, currentPageSize)
	const safeNextPageSize = Math.max(1, nextPageSize)
	const offset = (safeCurrentPage - 1) * safeCurrentPageSize
	return Math.min(Math.max(1, Math.floor(offset / safeNextPageSize) + 1), tracePageCount(total, safeNextPageSize))
}

function measureTraceTablePageSize(list: HTMLElement | null, maxPageSize?: number): number | null {
	if (!list) {
		return null
	}
	const header = list.querySelector<HTMLElement>('.trace-table-header')
	const rows = Array.from(list.querySelectorAll<HTMLElement>('.trace-table-row'))
	if (rows.length === 0) {
		return null
	}
	const rowHeights = rows.map((row) => row.getBoundingClientRect().height).filter((height) => height > 0)
	if (rowHeights.length === 0) {
		return null
	}
	const rowHeight = rowHeights.reduce((total, height) => total + height, 0) / rowHeights.length
	if (rowHeight <= 0) {
		return null
	}
	const listHeight = list.getBoundingClientRect().height
	if (listHeight <= 0) {
		return null
	}
	const availableHeight = listHeight - (header?.getBoundingClientRect().height ?? 0)
	if (availableHeight <= 0) {
		return 1
	}
	const pageSize = Math.max(1, Math.floor(availableHeight / rowHeight))
	return typeof maxPageSize === 'number' ? Math.min(pageSize, maxPageSize) : pageSize
}

function toggleNumberFilter(values: number[], value: number): number[] {
	return values.includes(value) ? values.filter((item) => item !== value) : [...values, value].sort((a, b) => a - b)
}

function pretty(value: unknown): string {
  try {
    const json = JSON.stringify(value, null, 2)
    return json === undefined ? String(value) : json
  } catch {
    return String(value)
  }
}

function issueToneClass(severity?: string): string {
  if (severity === 'error') {
    return 'tone-error'
  }
  if (severity === 'warning') {
    return 'tone-warning'
  }
  return 'tone-ok'
}

function issueBadgeClass(severity?: string): string {
  return `badge outline ${severity === 'error' ? 'idle' : severity === 'warning' ? 'warn' : 'live'}`
}

function issueLocation(issue: DoctorIssue): string {
  return issue.path || issue.directory || issue.providerKey || issue.protocol || ''
}

function renderIssue(issue: DoctorIssue, key: string) {
  const location = issueLocation(issue)
  return (
    <div className="issue-card" key={key}>
      <div className="issue-card-head">
        <span className={issueBadgeClass(issue.severity)}>{issue.severity || 'info'}</span>
        {issue.code ? <code>{issue.code}</code> : null}
        {issue.protocol ? <span className={protocolBadgeClass(issue.protocol as ProviderProtocol)}>{protocolLabel(issue.protocol as ProviderProtocol)}</span> : null}
      </div>
      <div className={issueToneClass(issue.severity)}>{issue.message}</div>
      {location ? <div className="subtle">{location}</div> : null}
      {issue.expected || issue.actual ? <div className="subtle">{issue.expected ? `expected: ${issue.expected}` : ''}{issue.expected && issue.actual ? ' | ' : ''}{issue.actual ? `actual: ${issue.actual}` : ''}</div> : null}
      {issue.actionHint ? <div className="subtle">{issue.actionHint}</div> : null}
      {issue.details && issue.details.length > 0 ? <div className="subtle">{issue.details.join(' | ')}</div> : null}
    </div>
  )
}

function renderReconciliationSummary(summary?: OpenCodeReconciliationSummary) {
  if (!summary) {
    return null
  }
  const facts = [
    `runtime ${summary.runtimeReachable ? 'reachable' : 'unreachable'}`,
    `file ${summary.fileSnapshotAvailable ? 'loaded' : 'unavailable'}`,
    `aliases ${(summary.availableAliases || []).length}`,
    `missing ${(summary.missingProviders || []).length}`,
    `catalog drift ${(summary.catalogMismatches || []).length}`,
  ]
  return <div className="issue-summary subtle">{facts.join(' · ')}</div>
}

function syncOutputChanged(value: SyncPreview | SyncResult): boolean {
  return 'changed' in value ? value.changed : value.wouldChange
}

type SyncDiffStatus = NonNullable<SyncPreview['aliasPreviews']>[number]['entries'][number]['status']
type SyncAliasPreview = NonNullable<SyncPreview['aliasPreviews']>[number]
type SyncDiffEntryPreview = SyncAliasPreview['entries'][number]
type SyncDiffSummary = NonNullable<SyncPreview['overallSummary']>
type SyncDiffProtocolFilter = ProviderProtocol | 'all'

const syncDiffProtocolFilters: SyncDiffProtocolFilter[] = ['all', 'openai-responses', 'anthropic-messages', 'openai-compatible']

function hasSyncDiffPreview(value: SyncPreview | SyncResult): boolean {
  return Array.isArray(value.aliasPreviews)
}

function normalizeSyncDiffSummary(summary?: Partial<SyncDiffSummary>): SyncDiffSummary {
  return {
    total: summary?.total || 0,
    new: summary?.new || 0,
    changed: summary?.changed || 0,
    unchanged: summary?.unchanged || 0,
    conflict: summary?.conflict || 0,
    failed: summary?.failed || 0,
  }
}

function normalizeSyncDiffEntries(entries: unknown): SyncDiffEntryPreview[] {
  if (!Array.isArray(entries)) {
    return []
  }
  return entries.filter((entry): entry is SyncDiffEntryPreview => typeof entry === 'object' && entry !== null)
}

function normalizeSyncAliasPreview(value: unknown): SyncAliasPreview | null {
  if (typeof value !== 'object' || value === null) {
    return null
  }
  const alias = value as Partial<SyncAliasPreview>
  const entries = normalizeSyncDiffEntries(alias.entries)
  return {
    aliasName: alias.aliasName || '',
    protocol: alias.protocol || 'openai-responses',
    providerKey: alias.providerKey || '',
    entries,
    summary: normalizeSyncDiffSummary(alias.summary),
  }
}

function syncDiffStatusKey(status: SyncDiffStatus): string {
  return status === 'new'
    ? 'sync.diffStatusNew'
    : status === 'changed'
      ? 'sync.diffStatusChanged'
      : status === 'unchanged'
        ? 'sync.diffStatusUnchanged'
        : status === 'conflict'
          ? 'sync.diffStatusConflict'
          : 'sync.diffStatusFailed'
}

function syncDiffStatusBadgeClass(status: SyncDiffStatus): string {
  return `badge status-badge sync-diff-status sync-diff-status-${status}`
}

function syncDiffStatusIcon(status: SyncDiffStatus): string {
  return status === 'new' ? '✚' : status === 'changed' ? '↻' : status === 'unchanged' ? '✓' : status === 'conflict' ? '⚠' : '✖'
}

function syncDiffNeedsAttention(alias: SyncAliasPreview): boolean {
  return (alias.summary?.conflict || 0) > 0 || (alias.summary?.failed || 0) > 0
}

function syncDiffSummaryWithFallback(summary?: SyncDiffSummary, aliases?: SyncAliasPreview[]): SyncDiffSummary {
  if (summary) {
    return normalizeSyncDiffSummary(summary)
  }
  return (aliases || []).reduce<SyncDiffSummary>(
    (total, alias) => ({
      total: total.total + (alias.summary?.total || alias.entries.length),
      new: total.new + (alias.summary?.new || 0),
      changed: total.changed + (alias.summary?.changed || 0),
      unchanged: total.unchanged + (alias.summary?.unchanged || 0),
      conflict: total.conflict + (alias.summary?.conflict || 0),
      failed: total.failed + (alias.summary?.failed || 0),
    }),
    { total: 0, new: 0, changed: 0, unchanged: 0, conflict: 0, failed: 0 },
  )
}

function syncDiffValuePreview(value: unknown, emptyValue: string): string {
  if (value === undefined) {
    return emptyValue
  }
  if (typeof value === 'string') {
    return value
  }
  return pretty(value)
}

function syncDiffEntryHint(entry: SyncDiffEntryPreview, emptyValue: string): string {
  if (entry.conflictNote) {
    return entry.conflictNote
  }
  if (entry.status === 'conflict') {
    return i18n.t('sync.diffConflictHint', {
      value: syncDiffValuePreview(entry.proposedValue, emptyValue),
      source: entry.autoDetected ? i18n.t('sync.diffAutoDetected') : i18n.t('sync.diffManual'),
    })
  }
  if (entry.status === 'failed') {
    return i18n.t('sync.diffFailedHint', { value: syncDiffValuePreview(entry.proposedValue, emptyValue) })
  }
  return ''
}

function SyncDiffStatusBadge({ status, label }: { status: SyncDiffStatus; label: string }) {
  return (
    <span className={syncDiffStatusBadgeClass(status)}>
      <span aria-hidden="true">{syncDiffStatusIcon(status)}</span> {label}
    </span>
  )
}

function SyncDiffJsonDetails({ summary, children }: { summary: { expand: string; collapse: string }; children: ReactNode }) {
  const [open, setOpen] = useState(false)
  return (
    <details className="details-toggle" open={open} onToggle={(event) => setOpen(event.currentTarget.open)}>
      <summary>{open ? summary.collapse : summary.expand}</summary>
      {children}
    </details>
  )
}

function SyncDiffAliasDetails({ alias, statusItems, emptyValue }: { alias: SyncAliasPreview; statusItems: SyncDiffStatus[]; emptyValue: string }) {
  const [open, setOpen] = useState(() => syncDiffNeedsAttention(alias))

  return (
    <details
      className="details-toggle issue-collapse"
      open={open}
      onToggle={(event) => setOpen(event.currentTarget.open)}
    >
      <summary>
        <span>{alias.aliasName}</span> · <span className={protocolBadgeClass(alias.protocol)}>{protocolLabel(alias.protocol)}</span> ·{' '}
        <code>{alias.providerKey}</code>
        {syncDiffNeedsAttention(alias) ? (
          <span className={syncDiffStatusBadgeClass((alias.summary?.failed || 0) > 0 ? 'failed' : 'conflict')}>
            {i18n.t((alias.summary?.failed || 0) > 0 ? 'sync.diffStatusFailed' : 'sync.diffStatusConflict')}
          </span>
        ) : null}
      </summary>
      <div className="stack-blocks">
        <div className="resource-card-meta sync-diff-summary-grid">
          <div className="resource-meta-item">
            <span className="resource-meta-label">{i18n.t('sync.diffProvider')}</span>
            <span className="resource-meta-value">{alias.providerKey}</span>
          </div>
          {statusItems.map((status) => (
            <div className="resource-meta-item" key={status}>
              <span className="resource-meta-label">{i18n.t(syncDiffStatusKey(status))}</span>
              <span className="resource-meta-value">{alias.summary?.[status] || 0}</span>
            </div>
          ))}
        </div>
        <div className="trace-table sync-diff-table" role="table" aria-label={i18n.t('sync.diffTitle')}>
          <div className="trace-table-header" role="row">
            <span className="trace-table-head" role="columnheader">{i18n.t('sync.diffField')}</span>
            <span className="trace-table-head" role="columnheader">{i18n.t('sync.diffCurrentValue')}</span>
            <span className="trace-table-head" role="columnheader">{i18n.t('sync.diffProposedValue')}</span>
            <span className="trace-table-head trace-table-head-end" role="columnheader">{i18n.t('sync.diffStatus')}</span>
          </div>
          <div className="trace-table-body">
            {alias.entries.map((entry, index) => {
              const hint = syncDiffEntryHint(entry, emptyValue)
              return (
                <article className="trace-table-row" role="row" key={`${alias.aliasName}-${entry.path || index}-${entry.status || 'unknown'}`}>
                  <div className="trace-table-cell" role="cell" data-label={i18n.t('sync.diffField')}>
                    <code>{entry.path || `#${index + 1}`}</code>
                    <span className="trace-table-muted">
                      {entry.autoDetected ? i18n.t('sync.diffAutoDetected') : i18n.t('sync.diffManual')}
                    </span>
                  </div>
                  <div className="trace-table-cell" role="cell" data-label={i18n.t('sync.diffCurrentValue')}>
                    <pre className="details sync-diff-value">{syncDiffValuePreview(entry.userValue, emptyValue)}</pre>
                  </div>
                  <div className="trace-table-cell" role="cell" data-label={i18n.t('sync.diffProposedValue')}>
                    <pre className="details sync-diff-value">{syncDiffValuePreview(entry.proposedValue, emptyValue)}</pre>
                  </div>
                  <div className="trace-table-cell trace-status-cell" role="cell" data-label={i18n.t('sync.diffStatus')}>
                    <SyncDiffStatusBadge status={entry.status || 'failed'} label={i18n.t(syncDiffStatusKey(entry.status || 'failed'))} />
                    {hint ? (
                      <TraceInfoPopover label={hint}>
                        <span className={`subtle ${entry.status === 'failed' ? 'tone-error' : 'tone-warning'}`}>{hint}</span>
                      </TraceInfoPopover>
                    ) : null}
                  </div>
                </article>
              )
            })}
          </div>
        </div>
        <SyncDiffJsonDetails summary={{ expand: i18n.t('sync.diffExpandJson'), collapse: i18n.t('sync.diffCollapseJson') }}>
          <pre className="details">{pretty(alias)}</pre>
        </SyncDiffJsonDetails>
      </div>
    </details>
  )
}

function SyncDiffPreview({
  output,
  protocolFilter,
  onProtocolFilterChange,
}: {
  output: SyncPreview | SyncResult
  protocolFilter: SyncDiffProtocolFilter
  onProtocolFilterChange: (protocol: SyncDiffProtocolFilter) => void
}) {
  if (!hasSyncDiffPreview(output)) {
    return null
  }
  const aliases = (output.aliasPreviews || [])
    .map(normalizeSyncAliasPreview)
    .filter((alias): alias is SyncAliasPreview => alias !== null)
  const filteredAliases = protocolFilter === 'all' ? aliases : aliases.filter((alias) => alias.protocol === protocolFilter)
  const visibleSummary = syncDiffSummaryWithFallback(protocolFilter === 'all' ? output.overallSummary : undefined, filteredAliases)
  const statusItems: SyncDiffStatus[] = ['new', 'changed', 'unchanged', 'conflict', 'failed']
  const emptyValue = i18n.t('sync.diffEmptyValue')

  return (
    <section className="issue-card sync-diff-preview">
      <div className="issue-card-head">
        <div>
          <strong>{i18n.t('sync.diffTitle')}</strong>
          <p className="subtle">{i18n.t('sync.diffSubtitle')}</p>
        </div>
      </div>
      <div className="toolbar sync-diff-filter-tabs">
        {syncDiffProtocolFilters.map((filter) => (
          <button
            key={filter}
            type="button"
            className={protocolFilter === filter ? 'primary' : undefined}
            onClick={() => onProtocolFilterChange(filter)}
          >
            {filter === 'all' ? i18n.t('sync.diffFilterAll') : protocolLabel(filter)}
          </button>
        ))}
      </div>
      <p className="subtle">
        {i18n.t('sync.diffSummary', {
          aliases: filteredAliases.length,
          conflicts: visibleSummary.conflict,
          new: visibleSummary.new,
          failed: visibleSummary.failed,
        })}
      </p>
      <div className="resource-card-meta sync-diff-summary-grid">
        <div className="resource-meta-item">
          <span className="resource-meta-label">{i18n.t('sync.diffFieldsTotal')}</span>
          <span className="resource-meta-value">{visibleSummary.total}</span>
        </div>
        {statusItems.map((status) => (
          <div className="resource-meta-item" key={status}>
            <span className="resource-meta-label">{i18n.t(syncDiffStatusKey(status))}</span>
            <span className="resource-meta-value">{visibleSummary[status]}</span>
          </div>
        ))}
      </div>
      {aliases.length === 0 || filteredAliases.length === 0 ? <p className="subtle">{i18n.t('sync.diffNoChanges')}</p> : null}
      {filteredAliases.length > 0 ? (
        <div className="issue-stack">
          {filteredAliases.map((alias) => (
            <SyncDiffAliasDetails
              key={`${alias.protocol}-${alias.providerKey}-${alias.aliasName}`}
              alias={alias}
              statusItems={statusItems}
              emptyValue={emptyValue}
            />
          ))}
        </div>
      ) : null}
      <SyncDiffJsonDetails summary={{ expand: i18n.t('sync.diffExpandJson'), collapse: i18n.t('sync.diffCollapseJson') }}>
        <pre className="details">{pretty({ overallSummary: output.overallSummary, aliasPreviews: output.aliasPreviews })}</pre>
      </SyncDiffJsonDetails>
    </section>
  )
}

function overviewDebugSnapshot(overview: Overview | null) {
  if (!overview) {
    return null
  }
  return {
    ...overview,
    configPath: undefined,
  }
}

function formatError(error: unknown): string {
  if (error && typeof error === 'object' && 'outcome' in error) {
    const te = error as TransportError
    const code = te.outcome?.code || te.message
    const key = `transport.outcome.${code}`
    const localized = i18n.t(key)
    if (localized && localized !== key) {
      return localized
    }
    return code || String(error)
  }
  return error instanceof Error ? error.message : String(error)
}

function outcomeMessage(code: string | undefined): string {
  const safe = (code || 'internal_error').trim() || 'internal_error'
  const key = `transport.outcome.${safe}`
  const localized = i18n.t(key)
  return localized && localized !== key ? localized : safe
}

function lifecycleSelectionsFromState(map: Record<string, LifecycleSelectionEntry>): LifecycleSelection[] {
  return Object.entries(map)
    .filter(([choiceId, entry]) => choiceId.trim() && entry?.optionId?.trim())
    .map(([choiceId, entry]) => {
      const selection: LifecycleSelection = { choiceId, optionId: entry.optionId }
      if (entry.params && Object.keys(entry.params).length > 0) {
        selection.params = entry.params
      }
      return selection
    })
}

function firstSurvivingGroupId(
  providers: ProviderView[],
  providerId: string,
  removingGroupId: string,
): string {
  const provider = providers.find((item) => item.id === providerId)
  const removing = (removingGroupId || '').trim() || 'default'
  for (const group of provider?.groups || []) {
    if ((group.id || 'default') !== removing && !group.disabled) {
      return group.id || 'default'
    }
  }
  for (const group of provider?.groups || []) {
    if ((group.id || 'default') !== removing) {
      return group.id || 'default'
    }
  }
  return ''
}

function defaultParamsForLifecycleOption(
  optionId: string,
  choice: LifecycleChoice,
  providers: ProviderView[],
): Record<string, unknown> | undefined {
  const choiceParams = choice.params || {}
  if (optionId === 'rebind_target') {
    const providerId = String(choiceParams.providerId || '')
    const model = String(choiceParams.model || '')
    const removingGroup = String(choiceParams.groupId || '')
    const groupId = firstSurvivingGroupId(providers, providerId, removingGroup)
    return {
      providerId,
      groupId,
      model,
    }
  }
  if (optionId === 'replace_provider_groups') {
    const providerId = String(choiceParams.providerId || '')
    const removingGroup = String(choiceParams.groupId || '')
    const groupId = firstSurvivingGroupId(providers, providerId, removingGroup)
    if (!providerId || !groupId) {
      return { providerGroups: [] as Array<{ provider: string; group: string }> }
    }
    return { providerGroups: [{ provider: providerId, group: groupId }] }
  }
  if (optionId === 'replace_providers') {
    const providersList = (choiceParams.availableProviders as string[] | undefined) || []
    if (providersList.length > 0) {
      return { providers: providersList.slice(0, 1) }
    }
  }
  return undefined
}

function defaultLifecycleSelections(
  choices: LifecycleChoice[] | undefined,
  current: Record<string, LifecycleSelectionEntry> = {},
  providers: ProviderView[] = [],
): Record<string, LifecycleSelectionEntry> {
  const next: Record<string, LifecycleSelectionEntry> = { ...current }
  for (const choice of choices || []) {
    if (!choice?.id) {
      continue
    }
    if (!next[choice.id] && choice.options?.length) {
      const optionId = choice.options[0].id
      next[choice.id] = {
        optionId,
        params: defaultParamsForLifecycleOption(optionId, choice, providers),
      }
      continue
    }
    const existing = next[choice.id]
    if (existing && !existing.params) {
      next[choice.id] = {
        ...existing,
        params: defaultParamsForLifecycleOption(existing.optionId, choice, providers),
      }
    }
  }
  return next
}

function formatProviderGroupsParam(params?: Record<string, unknown>): string {
  const raw = params?.providerGroups
  if (!Array.isArray(raw)) {
    return ''
  }
  return raw
    .map((item) => {
      if (!item || typeof item !== 'object') {
        return ''
      }
      const row = item as { provider?: string; group?: string }
      const provider = (row.provider || '').trim()
      const group = (row.group || '').trim()
      if (!provider || !group) {
        return ''
      }
      return `${provider}/${group}`
    })
    .filter(Boolean)
    .join(', ')
}

function parseProviderGroupsParam(text: string): Array<{ provider: string; group: string }> {
  return text
    .split(/[\n,;]+/)
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const slash = part.indexOf('/')
      if (slash <= 0) {
        return { provider: part, group: 'default' }
      }
      return {
        provider: part.slice(0, slash).trim(),
        group: part.slice(slash + 1).trim() || 'default',
      }
    })
    .filter((item) => item.provider && item.group)
}

function formatLifecycleChangeLine(change: { kind?: string; entity?: string; reasonCode?: string; path?: string }): string {
  const parts = [change.kind, change.entity, change.reasonCode].filter(Boolean)
  if (change.path) {
    parts.push(change.path)
  }
  return parts.join(' · ')
}

function formatLifecycleIssueLine(issue: LifecycleIssue): string {
  const parts = [issue.code, issue.disposition, issue.path].filter(Boolean)
  return parts.join(' · ')
}

function headersTextFromMap(headers?: Record<string, string>): string {
  if (!headers || Object.keys(headers).length === 0) {
    return ''
  }
  return Object.entries(headers)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([key, value]) => `${key}=${value}`)
    .join('\n')
}

function parseHeadersText(input: string): Record<string, string> | undefined {
  const lines = input
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
  if (lines.length === 0) {
    return undefined
  }
  const headers: Record<string, string> = {}
  for (const line of lines) {
    const index = line.indexOf('=')
    if (index <= 0) {
      throw new Error(i18n.t('errors.invalidHeaderFormat', { line }))
    }
    const key = line.slice(0, index).trim().toLowerCase()
    const value = line.slice(index + 1).trim()
    if (!key) {
      throw new Error(i18n.t('errors.invalidHeaderName', { line }))
    }
    headers[key] = value
  }
  return headers
}

function stringifyRewriteValue(value: unknown): string {
  const json = JSON.stringify(value)
  return json === undefined ? String(value) : json
}

function stringifyRewriteOperation(op: RequestRewriteOperation): string {
  if (op.op === 'delete') {
    return `${op.op}:${op.path}`
  }
  if (op.op === 'insert') {
    return `${op.op}:${op.path}:${op.index ?? 0}=${stringifyRewriteValue(op.value)}`
  }
  return `${op.op}:${op.path}=${stringifyRewriteValue(op.value)}`
}

function rewriteOpsTextFromList(ops?: RequestRewriteOperation[]): string {
  if (!ops || ops.length === 0) {
    return ''
  }
  return ops.map((op) => stringifyRewriteOperation(op)).join('\n')
}

function parseRewriteValue(rawValue: string): unknown {
  if (rawValue === '') {
    return ''
  }
  try {
    return JSON.parse(rawValue)
  } catch {
    return rawValue
  }
}

function parseRewritePath(path: string, line: string): string {
  const trimmedPath = path.trim()
  if (!trimmedPath) {
    throw new Error(i18n.t('rewriteRules.errors.emptyPath', { line }))
  }
  if (trimmedPath === '$') {
    throw new Error(i18n.t('rewriteRules.errors.rootPath', { line }))
  }
  if (!trimmedPath.startsWith('$')) {
    throw new Error(i18n.t('rewriteRules.errors.pathMustStartWithRoot', { line }))
  }
  validateRewriteJSONPath(trimmedPath, line)
  return trimmedPath
}

function validateRewriteJSONPath(path: string, line: string): void {
  let index = 1
  let segmentCount = 0
  while (index < path.length) {
    const char = path[index]
    if (char === '.') {
      if (path[index + 1] === '.') {
        throw new Error(i18n.t('rewriteRules.errors.unsupportedPath', { line }))
      }
      const nextIndex = scanRewriteDotName(path, index + 1)
      if (nextIndex === index + 1) {
        throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
      }
      index = nextIndex
      segmentCount += 1
      continue
    }
    if (char === '[') {
      const nextIndex = scanRewriteBracketSegment(path, index, line)
      index = nextIndex
      segmentCount += 1
      continue
    }
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  if (segmentCount === 0) {
    throw new Error(i18n.t('rewriteRules.errors.rootPath', { line }))
  }
}

function scanRewriteDotName(path: string, start: number): number {
  if (start >= path.length || !isRewritePathNameStart(path[start])) {
    return start
  }
  let index = start + 1
  while (index < path.length && isRewritePathNameChar(path[index])) {
    index += 1
  }
  return index
}

function scanRewriteBracketSegment(path: string, start: number, line: string): number {
  let contentStart = start + 1
  while (contentStart < path.length && /\s/.test(path[contentStart])) {
    contentStart += 1
  }
  if (contentStart >= path.length) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  if (path[contentStart] === "'" || path[contentStart] === '"') {
    const quote = path[contentStart]
    let contentEnd = contentStart + 1
    while (contentEnd < path.length) {
      if (path[contentEnd] === '\\') {
        contentEnd += 2
        continue
      }
      if (path[contentEnd] === quote) {
        break
      }
      contentEnd += 1
    }
    if (contentEnd >= path.length) {
      throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
    }
    let end = contentEnd + 1
    while (end < path.length && /\s/.test(path[end])) {
      end += 1
    }
    if (end >= path.length || path[end] !== ']') {
      throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
    }
    validateRewriteQuotedName(path.slice(contentStart, contentEnd + 1), line)
    return end + 1
  }
  const end = path.indexOf(']', contentStart)
  if (end < 0) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  const content = path.slice(contentStart, end).trim()
  if (!content) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  if (/[*?:,]/.test(content)) {
    throw new Error(i18n.t('rewriteRules.errors.unsupportedPath', { line }))
  }
  if (!/^\d+$/.test(content)) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  return end + 1
}

function splitRewriteOpValue(input: string, line: string): [string, string] {
  for (let index = 0; index < input.length; index += 1) {
    const char = input[index]
    if (char === "'" || char === '"') {
      index = scanRewriteQuotedSpan(input, index, line)
      continue
    }
    if (char === '=') {
      return [input.slice(0, index), input.slice(index + 1)]
    }
  }
  throw new Error(i18n.t('rewriteRules.errors.invalidValueOpLine', { line }))
}

function splitRewriteInsertLeft(input: string, line: string): [string, string] {
  let separator = -1
  for (let index = 0; index < input.length; index += 1) {
    const char = input[index]
    if (char === "'" || char === '"') {
      index = scanRewriteQuotedSpan(input, index, line)
      continue
    }
    if (char === ':') {
      separator = index
    }
  }
  if (separator < 0) {
    throw new Error(i18n.t('rewriteRules.errors.insertIndexRequired', { line }))
  }
  return [input.slice(0, separator), input.slice(separator + 1)]
}

function scanRewriteQuotedSpan(input: string, start: number, line: string): number {
  const quote = input[start]
  for (let index = start + 1; index < input.length; index += 1) {
    if (input[index] === '\\') {
      index += 1
      continue
    }
    if (input[index] === quote) {
      return index
    }
  }
  throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
}

function validateRewriteQuotedName(content: string, line: string): void {
  const quote = content[0]
  if (content.length < 2 || content[content.length - 1] !== quote) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  if (content.length === 2) {
    throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
  }
  for (let index = 1; index < content.length - 1; index += 1) {
    if (content[index] !== '\\') {
      continue
    }
    index += 1
    if (index >= content.length - 1 || !['\\', '/', "'", '"', 'b', 'f', 'n', 'r', 't'].includes(content[index])) {
      throw new Error(i18n.t('rewriteRules.errors.invalidPath', { line }))
    }
  }
}

function isRewritePathNameStart(char: string): boolean {
  return char === '_' || /^\p{L}$/u.test(char)
}

function isRewritePathNameChar(char: string): boolean {
  return isRewritePathNameStart(char) || /^\d$/.test(char)
}

function parseRewriteInsertIndex(rawIndex: string, line: string): number {
  const trimmedIndex = rawIndex.trim()
  if (!trimmedIndex) {
    throw new Error(i18n.t('rewriteRules.errors.insertIndexRequired', { line }))
  }
  if (!/^\d+$/.test(trimmedIndex)) {
    throw new Error(i18n.t('rewriteRules.errors.insertIndexInvalid', { line }))
  }
  return Number(trimmedIndex)
}

function parseRewriteOpsText(input: string): RequestRewriteOperation[] | undefined {
  const lines = input
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
  if (lines.length === 0) {
    return undefined
  }
  const ops: RequestRewriteOperation[] = []
  for (const line of lines) {
    const colonIndex = line.indexOf(':')
    if (colonIndex <= 0) {
      throw new Error(i18n.t('rewriteRules.errors.invalidOpLine', { line }))
    }
    const opName = line.slice(0, colonIndex).trim().toLowerCase()
    const rest = line.slice(colonIndex + 1).trim()
    if (opName === 'set' || opName === 'append') {
      const [path, rawValue] = splitRewriteOpValue(rest, line)
      ops.push({
        op: opName,
        path: parseRewritePath(path, line),
        value: parseRewriteValue(rawValue.trim()),
      })
      continue
    }
    if (opName === 'delete') {
      if (rest.includes('=')) {
        throw new Error(i18n.t('rewriteRules.errors.invalidDeleteLine', { line }))
      }
      ops.push({ op: 'delete', path: parseRewritePath(rest, line) })
      continue
    }
    if (opName === 'insert') {
      const [left, rawValue] = splitRewriteOpValue(rest, line)
      const [path, rawIndex] = splitRewriteInsertLeft(left.trim(), line)
      ops.push({
        op: 'insert',
        path: parseRewritePath(path, line),
        index: parseRewriteInsertIndex(rawIndex, line),
        value: parseRewriteValue(rawValue.trim()),
      })
      continue
    }
    throw new Error(i18n.t('rewriteRules.errors.invalidOperation', { line }))
  }
  return ops
}

function rewriteRuleOpsCount(rule: RequestRewriteRuleView): number {
  return rule.ops?.length || 0
}

function rewriteRuleWarnings(rule: RequestRewriteRuleView): string[] {
  return rule.warnings || []
}

function rewriteRuleHasOverrideOnlyOps(ops: RequestRewriteOperation[]): boolean {
  return ops.some((op) => op.op === 'delete' || op.op === 'append' || op.op === 'insert')
}

function rewriteRuleFormFromView(rule: RequestRewriteRuleView, options?: RewriteRuleGroupOption[]): RewriteRuleFormState {
  const savedGroups = rule.providerGroups || []
  const providerGroups = savedGroups.length === 0
    ? null
    : options
    ? options
      .filter((option) => savedGroups.some((selector) => rewriteRuleGroupSelectorKey(selector) === option.id))
      .map((option) => ({ provider: option.provider, group: option.group }))
    : savedGroups.map((selector) => ({ provider: selector.provider, group: selector.group || 'default' }))
  return {
    name: rule.name,
    alias: rule.alias || '',
    providerGroups,
    enabled: rule.enabled,
    override: rule.override,
    opsText: rule.legacy ? '' : rewriteOpsTextFromList(rule.ops),
  }
}

function rewriteRuleInputFromForm(form: RewriteRuleFormState, options: RewriteRuleGroupOption[]): RequestRewriteRuleInput {
  const name = form.name.trim()
  const alias = form.alias.trim()
  if (!name) {
    throw new Error(i18n.t('rewriteRules.errors.nameRequired'))
  }
  if (!alias) {
    throw new Error(i18n.t('rewriteRules.errors.aliasRequired'))
  }
  const ops = parseRewriteOpsText(form.opsText)
  if (!ops || ops.length === 0) {
    throw new Error(i18n.t('rewriteRules.errors.operationRequired'))
  }
  if (rewriteRuleHasOverrideOnlyOps(ops) && !form.override) {
    throw new Error(i18n.t('rewriteRules.errors.overrideRequired'))
  }
  const optionIds = options.map((option) => option.id)
  if (optionIds.length > 0 && form.providerGroups !== null && rewriteRuleEffectiveGroupIds(form.providerGroups, optionIds).length === 0) {
    throw new Error(i18n.t('rewriteRules.providersHint'))
  }
  return {
    name,
    alias: alias || undefined,
    providerGroups: rewriteRuleGroupsForInput(form.providerGroups, options),
    enabled: form.enabled,
    override: form.override,
    ops,
  }
}

function rewriteRuleScopeText(rule: RequestRewriteRuleView, alias: AliasView | null, providers: ProviderView[]): string {
  if (rule.alias) {
    return i18n.t('rewriteRules.scopeAliasProviders', {
      alias: rule.alias,
      providers: rewriteRuleGroupScopeText(rule.providerGroups, alias, providers),
    })
  }
  return i18n.t('rewriteRules.scopeMissing')
}

function providerFormFromView(provider: ProviderView): ProviderFormState {
	const defaultGroup = providerDefaultGroup(provider)
  return {
    id: provider.id,
    name: provider.name || '',
		protocol: defaultGroup?.protocol || 'openai-responses',
    baseUrls: provider.baseUrls && provider.baseUrls.length > 0 ? [...provider.baseUrls] : [provider.baseUrl],
    baseUrlStrategy: provider.baseUrlStrategy || 'ordered',
    apiKeys: [''],
    apiKeysDirty: false,
    headersText: headersTextFromMap(provider.headers),
    disabled: provider.disabled,
    skipModels: false,
    clearHeaders: false,
    autoAliasEnabled: providerAutoAliasEnabled(provider),
  }
}

function providerEffectiveBaseUrls(provider: ProviderView | null): string[] {
	if (!provider) {
		return []
	}
	return provider.baseUrls && provider.baseUrls.length > 0 ? provider.baseUrls : [provider.baseUrl]
}

function providerBaseUrlSummary(provider: ProviderView | null, form: ProviderFormState, t: (key: string, options?: Record<string, unknown>) => string): string {
	const baseUrls = providerEffectiveBaseUrls(provider)
	if (baseUrls.length > 0) {
		return baseUrls.join('\n')
	}
	const draft = form.baseUrls.map((item) => item.trim()).filter(Boolean)
	if (draft.length > 0) {
		return draft.join('\n')
	}
	return t('providers.baseUrlsEmpty')
}

function aliasFormFromView(alias: AliasView): AliasFormState {
  return {
    alias: alias.alias,
    displayName: alias.displayName || '',
    protocol: alias.protocol,
    disabled: !alias.enabled,
  }
}

function joinWarnings(warnings?: string[]): string {
  if (!warnings || warnings.length === 0) {
    return ''
  }
  return warnings.join(' | ')
}

function withWarnings(base: string, warnings?: string[]): string {
  const merged = joinWarnings(warnings)
  if (!merged) {
    return base
  }
  return `${base}. ${i18n.t('messages.warningsSuffix', { warnings: merged })}`
}

function providerSaveStatus(result: ProviderSaveResult): string {
  return withWarnings(i18n.t('providers.statusSaved', { id: providerDisplayLabel(result.provider.id, [result.provider]) }), result.warnings)
}

function providerImportStatus(result: ProviderImportResult): string {
  return withWarnings(
    i18n.t('providers.statusImportDone', { imported: result.imported, skipped: result.skipped }),
    result.warnings,
  )
}

function desktopPrefsSaveStatus(result: DesktopPrefsSaveResult): string {
  return withWarnings(i18n.t('messages.saved'), result.warnings)
}

function proxySettingsSaveStatus(result: ProxySettingsSaveResult): string {
  return withWarnings(i18n.t('messages.saved'), result.warnings)
}

function providerApiKeySummary(provider: ProviderView | null, form: ProviderFormState, t: (key: string, options?: Record<string, unknown>) => string): string {
	const masked = providerDefaultGroup(provider)?.apiKeysMasked || []
	if (masked.length > 0) {
		return masked.map((item, index) => t('providers.apiKeySummaryItem', { index: index + 1, key: item })).join('\n')
	}
	const draftCount = form.apiKeys.map((item) => item.trim()).filter(Boolean).length
	if (draftCount > 0) {
		return t('providers.apiKeyDraftCount', { count: draftCount })
	}
	return t('providers.apiKeyNotSet')
}

function formatFailoverStatusCodes(statusCodes: number[] | undefined): string {
  return (statusCodes || []).join(', ')
}

function normalizeProxySettingsView(settings: ProxySettingsView): ProxySettingsView {
  return {
    ...settings,
    streamPrecommitBufferMs: Math.max(0, settings.streamPrecommitBufferMs || 0),
    excludeFirstTokenLatencyFromRate: settings.excludeFirstTokenLatencyFromRate !== false,
    failoverStatusCodes: settings.failoverStatusCodes || [],
  }
}

function parseFailoverStatusCodes(value: string): number[] {
  const statusCodes = new Set<number>()
  for (const token of value.trim().split(/[\s,]+/).filter(Boolean)) {
    if (!/^\d+$/.test(token)) {
      throw new Error(i18n.t('settings.failoverStatusCodesInvalidToken', { value: token }))
    }
    const statusCode = Number(token)
    if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
      throw new Error(i18n.t('settings.failoverStatusCodesInvalidRange', { value: token }))
    }
    statusCodes.add(statusCode)
  }
  return [...statusCodes].sort((left, right) => left - right)
}

function activeRoutingDescriptor(proxySettings: ProxySettingsView): RoutingStrategyDescriptor | null {
	return proxySettings.routing.descriptors?.find((item) => item.name === proxySettings.routing.strategy) || null
}

function routingI18nBase(strategyName: string): string | null {
	if (strategyName === 'circuit-breaker') {
		return 'settings.routing.circuitBreaker'
	}
	return null
}

function routingStrategyLabel(descriptor: RoutingStrategyDescriptor): string {
	const key = routingI18nBase(descriptor.name)
	return key ? i18n.t(`${key}.displayName`, { defaultValue: descriptor.displayName }) : descriptor.displayName
}

function routingStrategyDescription(descriptor: RoutingStrategyDescriptor): string {
	const key = routingI18nBase(descriptor.name)
	return key ? i18n.t(`${key}.description`, { defaultValue: descriptor.description || '' }) : (descriptor.description || '')
}

function routingParameterLabel(strategyName: string, parameter: RoutingStrategyParamSpec): string {
	const key = routingI18nBase(strategyName)
	return key ? i18n.t(`${key}.params.${parameter.key}.label`, { defaultValue: parameter.description || parameter.key }) : (parameter.description || parameter.key)
}

function routingParameterDescription(strategyName: string, parameter: RoutingStrategyParamSpec): string {
	const key = routingI18nBase(strategyName)
	return key ? i18n.t(`${key}.params.${parameter.key}.description`, { defaultValue: parameter.description || '' }) : (parameter.description || '')
}

function updateRoutingParam(current: ProxySettingsView, key: string, value: unknown): ProxySettingsView {
	return {
		...current,
		routing: {
			...current.routing,
			params: {
				...(current.routing.params || {}),
				[key]: value,
			},
		},
	}
}

function routingParamInput(
	proxySettings: ProxySettingsView,
	strategyName: string,
	parameter: RoutingStrategyParamSpec,
	onChange: (next: ProxySettingsView) => void,
) {
	const value = proxySettings.routing.params?.[parameter.key] ?? parameter.defaultValue
	if (parameter.type === 'bool') {
		return (
			<label className="checkbox-row" key={parameter.key}>
				<input
					type="checkbox"
					checked={Boolean(value)}
					onChange={(event) => onChange(updateRoutingParam(proxySettings, parameter.key, event.target.checked))}
				/>
				<span>{routingParameterLabel(strategyName, parameter)}</span>
			</label>
		)
	}
	if (parameter.enum && parameter.enum.length > 0) {
		return (
			<label key={parameter.key}>
				<span>{routingParameterLabel(strategyName, parameter)}</span>
				<select value={String(value ?? '')} onChange={(event) => onChange(updateRoutingParam(proxySettings, parameter.key, event.target.value))}>
					{parameter.enum.map((option) => (
						<option key={option} value={option}>{option}</option>
					))}
				</select>
				{routingParameterDescription(strategyName, parameter) ? <p className="subtle">{routingParameterDescription(strategyName, parameter)}</p> : null}
			</label>
		)
	}
	return (
		<label key={parameter.key}>
			<span>{routingParameterLabel(strategyName, parameter)}</span>
			<input
				type="number"
				min={parameter.min}
				max={parameter.max}
				step={parameter.type === 'float' ? '0.1' : 1}
				value={typeof value === 'number' ? value : Number(value) || 0}
				onChange={(event) => onChange(updateRoutingParam(proxySettings, parameter.key, parameter.type === 'float' ? Number(event.target.value) || 0 : Math.trunc(Number(event.target.value) || 0)))}
			/>
			{routingParameterDescription(strategyName, parameter) ? <p className="subtle">{routingParameterDescription(strategyName, parameter)}</p> : null}
		</label>
	)
}

function normalizeTab(hash: string): TabKey {
  const value = hash.replace(/^#/, '')
  return tabs.includes(value as TabKey) ? (value as TabKey) : 'overview'
}

function visibleTabsForMeta(meta: MetaState): TabKey[] {
  void meta
  return tabs
}

function resolveThemePreference(theme: ThemePreference, systemTheme: ResolvedTheme): ResolvedTheme {
  if (theme === 'light' || theme === 'dark') {
    return theme
  }
  return systemTheme
}

function configFileName(configPath: string): string {
  const parts = configPath.split(/[/\\]/).filter(Boolean)
  return parts[parts.length - 1] || 'ocswitch-config.json'
}

function formatDateTime(value?: string): string {
  if (!value) {
    return '-'
  }
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) {
    return value
  }
  return date.toLocaleString()
}

function formatCompactDateTime(value?: string): string {
	if (!value) {
		return '-'
	}
	const date = new Date(value)
	if (Number.isNaN(date.getTime())) {
		return value
	}
	const month = String(date.getMonth() + 1).padStart(2, '0')
	const day = String(date.getDate()).padStart(2, '0')
	const hours = String(date.getHours()).padStart(2, '0')
	const minutes = String(date.getMinutes()).padStart(2, '0')
	const seconds = String(date.getSeconds()).padStart(2, '0')
	return `${month}-${day} ${hours}:${minutes}:${seconds}`
}

function dateToLocalDateTimeInput(date: Date): string {
	const year = date.getFullYear()
	const month = String(date.getMonth() + 1).padStart(2, '0')
	const day = String(date.getDate()).padStart(2, '0')
	const hours = String(date.getHours()).padStart(2, '0')
	const minutes = String(date.getMinutes()).padStart(2, '0')
	return `${year}-${month}-${day}T${hours}:${minutes}`
}

function localDateTimeInputToISO(value: string): string | undefined {
	if (!value) {
		return undefined
	}
	const date = new Date(value)
	return Number.isNaN(date.getTime()) ? undefined : date.toISOString()
}

function normalizeCustomTraceRange(start: string, end: string): { startedFrom?: string; startedTo?: string } {
	const startedFrom = localDateTimeInputToISO(start)
	const startedTo = localDateTimeInputToISO(end)
	if (startedFrom && startedTo && new Date(startedFrom).getTime() > new Date(startedTo).getTime()) {
		return { startedFrom: startedTo, startedTo: startedFrom }
	}
	return { startedFrom, startedTo }
}

function startOfToday(date: Date): Date {
	const start = new Date(date)
	start.setHours(0, 0, 0, 0)
	return start
}

function startOfWeek(date: Date): Date {
	const start = startOfToday(date)
	const day = start.getDay()
	start.setDate(start.getDate() - (day === 0 ? 6 : day - 1))
	return start
}

function traceTimeRange(filter: TraceTimeFilterState, proxyStartedAt?: string): { startedFrom?: string; startedTo?: string } {
	if (filter.preset === 'run') {
		return proxyStartedAt ? { startedFrom: proxyStartedAt } : {}
	}
	if (filter.preset === 'today') {
		return { startedFrom: startOfToday(new Date()).toISOString() }
	}
	if (filter.preset === 'week') {
		return { startedFrom: startOfWeek(new Date()).toISOString() }
	}
	return normalizeCustomTraceRange(filter.start, filter.end)
}

function formatTraceRangeValue(range: { startedFrom?: string; startedTo?: string }): string {
	if (!range.startedFrom && !range.startedTo) {
		return i18n.t('trace.timeAll')
	}
	return i18n.t('trace.timeRangeValue', {
		start: range.startedFrom ? formatDateTime(range.startedFrom) : i18n.t('trace.timeEarliest'),
		end: range.startedTo ? formatDateTime(range.startedTo) : i18n.t('trace.timeNow'),
	})
}

function formatDuration(value?: number): string {
  if (value == null) {
    return '-'
  }
  return `${value} ms`
}

function formatCompactDuration(value?: number): string {
	if (value == null) {
		return '-'
	}
	if (value >= 1000) {
		return `${(value / 1000).toFixed(2)} s`
	}
	return `${Math.round(value)} ms`
}

function formatHealthDuration(value?: number): string {
	if (value == null) {
		return '-'
	}
	let seconds = Math.max(0, Math.round(value / 1000))
	const hours = Math.floor(seconds / 3600)
	seconds %= 3600
	const minutes = Math.floor(seconds / 60)
	seconds %= 60
	const parts: string[] = []
	if (hours > 0) {
		parts.push(`${hours}h`)
	}
	if (minutes > 0 || hours > 0) {
		parts.push(`${minutes}m`)
	}
	parts.push(`${seconds}s`)
	return parts.join('')
}

function formatTokenCount(value?: number): string {
  if (value == null) {
    return '-'
  }
  return value.toLocaleString()
}

function formatCompactCount(value?: number): string {
	if (value == null) {
		return '-'
	}
	if (Math.abs(value) < 10000) {
		return value.toLocaleString()
	}
	return new Intl.NumberFormat('en-US', {
		notation: 'compact',
		maximumFractionDigits: 1,
	}).format(value)
}

function formatUsageText(value?: number | string): string {
  if (value == null || value === '') {
    return '-'
  }
  if (typeof value === 'number') {
    return value.toLocaleString()
  }
  return value
}

function formatPercent(value?: number): string {
	if (value == null || Number.isNaN(value)) {
		return '-'
	}
	return `${Math.round(value * 100)}%`
}

function formatHealthPercent(value?: number): string {
	if (value == null || Number.isNaN(value)) {
		return '-'
	}
	return `${new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value * 100)}%`
}

function formatTokenMillions(value?: number): string {
	if (value == null || Number.isNaN(value)) {
		return '-'
	}
	return `${new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value / 1_000_000)}M`
}

function formatHealthRole(role: string): string {
	return i18n.t(`health.role.${role}`, { defaultValue: role || '-' })
}

function formatHealthSampleLevel(level: string): string {
	return i18n.t(`health.sample.${level}`, { defaultValue: level || '-' })
}

function healthSampleBadgeClass(level: string): string {
	return level === 'ok' ? 'live' : level === 'low' ? 'warn' : 'idle'
}

function providerHealthFailureText(provider: ProviderHealthView): string {
	return [
		provider.rateLimited > 0 ? i18n.t('health.failure429', { count: provider.rateLimited }) : '',
		provider.upstream5xx > 0 ? i18n.t('health.failure5xx', { count: provider.upstream5xx }) : '',
		provider.timeouts > 0 ? i18n.t('health.failureTimeout', { count: provider.timeouts }) : '',
		provider.transportErrors > 0 ? i18n.t('health.failureTransport', { count: provider.transportErrors }) : '',
	]
		.filter(Boolean)
		.join(' · ') || '-'
}

function providerHealthPrimaryAlias(provider: ProviderHealthView): string {
	const first = provider.aliases?.[0]
	if (!first) {
		return '-'
	}
	const extra = provider.aliases && provider.aliases.length > 1 ? ` +${provider.aliases.length - 1}` : ''
	return `${first.alias} #${first.targetIndex + 1}${extra}`
}

function providerHealthCacheHitRate(provider: ProviderHealthView): string {
	return provider.cacheReadTokens + provider.inputTokens > 0 ? formatPercent(provider.cacheHitRate) : '-'
}

function isProviderProtocol(value?: string): value is ProviderProtocol {
  return value === 'openai-responses' || value === 'anthropic-messages' || value === 'openai-compatible'
}

function providerHealthProtocol(provider: ProviderHealthView): ProviderProtocol | null {
	return isProviderProtocol(provider.protocol) ? provider.protocol : null
}

function modelHealthDisplay(model: ProviderModelHealthView, providers: ProviderView[]): { label: string; title: string } {
	const group = model.group || 'default'
	return {
		label: providerModelDisplay(model.provider, model.model, providers),
		title: `${model.provider}/${group}/${model.model}`,
	}
}

function modelHealthInputOutputTokens(model: ProviderModelHealthView): number {
	return model.inputTokens + model.outputTokens
}

type ProviderModelHealthGroup = {
	provider: string
	label: string
	title?: string
	totalTokens: number
	items: ProviderModelHealthView[]
}

function groupProviderModelHealth(items: ProviderModelHealthView[], providers: ProviderView[]): ProviderModelHealthGroup[] {
	const groups: ProviderModelHealthGroup[] = []
	const byProvider = new Map<string, ProviderModelHealthGroup>()
	for (const item of items) {
		let group = byProvider.get(item.provider)
		if (!group) {
			group = {
				provider: item.provider,
				label: providerDisplayLabel(item.provider, providers),
				title: providerDisplayTitle(item.provider, providers),
				totalTokens: 0,
				items: [],
			}
			byProvider.set(item.provider, group)
			groups.push(group)
		}
		group.totalTokens += item.totalTokens
		group.items.push(item)
	}
	return groups
}

function usageSourceLabel(source?: string): string {
  if (!source) {
    return '-'
  }
  if (isProviderProtocol(source)) {
    return protocolLabel(source)
  }
  return source
}

function usageSourceBadgeClass(source?: string): string {
  if (isProviderProtocol(source)) {
    return protocolBadgeClass(source)
  }
  return 'badge outline'
}

function usagePrecisionLabel(precision?: string): string {
  switch (precision) {
    case 'exact':
      return i18n.t('log.usagePrecisionValues.exact')
    case 'partial':
      return i18n.t('log.usagePrecisionValues.partial')
    case 'unavailable':
      return i18n.t('log.usagePrecisionValues.unavailable')
    default:
      return formatUsageText(precision)
  }
}

function usagePrecisionBadgeClass(precision?: string): string {
  switch (precision) {
    case 'exact':
      return 'badge live'
    case 'partial':
      return 'badge warn'
    case 'unavailable':
      return 'badge outline idle'
    default:
      return 'badge outline'
  }
}

function traceGeneratedOutputTokens(trace: RequestTrace): number | null {
	if (typeof trace.generatedOutputTokens === 'number' && trace.generatedOutputTokens > 0) {
		return trace.generatedOutputTokens
	}
	if (typeof trace.usage?.rawOutputTokens === 'number' && trace.usage.rawOutputTokens > 0) {
		return trace.usage.rawOutputTokens
	}
	const outputTokens = trace.usage?.outputTokens ?? trace.outputTokens
	const reasoningTokens = trace.usage?.reasoningTokens
	const generated = (outputTokens || 0) + (reasoningTokens || 0)
	if (generated > 0) {
		return generated
	}
	return null
}

function traceRateDurationMs(trace: RequestTrace, excludeFirstTokenLatency: boolean): number | null {
	if (!trace.durationMs || trace.durationMs <= 0) {
		return null
	}
	if (!excludeFirstTokenLatency) {
		return trace.durationMs
	}
	if (typeof trace.firstTokenMs !== 'number' || trace.firstTokenMs <= 0 || trace.durationMs <= trace.firstTokenMs) {
		return null
	}
	return trace.durationMs - trace.firstTokenMs
}

function formatTokenRate(trace: RequestTrace, excludeFirstTokenLatency: boolean): string {
  const tokens = traceGeneratedOutputTokens(trace)
  const rateDuration = traceRateDurationMs(trace, excludeFirstTokenLatency)
  if (!tokens || !rateDuration) {
    return '-'
  }
  return `${((tokens * 1000) / rateDuration).toFixed(1)} token/s`
}

function formatCompactTokenRate(trace: RequestTrace, excludeFirstTokenLatency: boolean): string {
	const tokens = traceGeneratedOutputTokens(trace)
	const rateDuration = traceRateDurationMs(trace, excludeFirstTokenLatency)
	if (!tokens || !rateDuration) {
		return '-'
	}
	return `${((tokens * 1000) / rateDuration).toFixed(2)} tok/s`
}

function traceTotalTokens(trace: RequestTrace): number | null {
	if (typeof trace.usage?.rawTotalTokens === 'number') {
		return trace.usage.rawTotalTokens
	}
	const inputTokens = trace.inputTokens ?? trace.usage?.inputTokens ?? trace.usage?.rawInputTokens
	const outputTokens = traceGeneratedOutputTokens(trace) ?? trace.outputTokens ?? trace.usage?.outputTokens ?? trace.usage?.rawOutputTokens
	if (typeof inputTokens === 'number' || typeof outputTokens === 'number') {
		return (inputTokens || 0) + (outputTokens || 0)
	}
	return null
}

function traceDisplayModel(trace: RequestTrace): string {
	return trace.finalModel || trace.alias || trace.rawModel || `#${trace.id}`
}

