function tracePrimaryText(trace: RequestTrace, providers: ProviderView[] = []): string {
  if (trace.finalProvider && trace.finalModel) {
    return providerModelDisplay(trace.finalProvider, trace.finalModel, providers)
  }
  if (trace.finalProvider) {
    return providerDisplayLabel(trace.finalProvider, providers)
  }
  return trace.error || i18n.t('messages.noData')
}

function downloadTextFile(filename: string, content: string) {
  const blob = new Blob([content], { type: 'application/json;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.append(link)
  link.click()
  link.remove()
  URL.revokeObjectURL(url)
}

function focusableElements(root: HTMLElement): HTMLElement[] {
  return Array.from(
    root.querySelectorAll<HTMLElement>(
      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
    ),
  )
}

function focusFirstInput(root: HTMLElement | null) {
  if (!root) {
    return
  }
  const target = root.querySelector<HTMLElement>(
    'input:not([disabled]):not([type="checkbox"]), select:not([disabled]), textarea:not([disabled])',
  )
  ;(target || root).focus()
}

function focusFirstFocusable(root: HTMLElement | null) {
  if (!root) {
    return
  }
  const [firstFocusable] = focusableElements(root)
  ;(firstFocusable || root).focus()
}

function scrollInvalidControlIntoView(event: FormEvent<HTMLFormElement>, setStatus: (value: string) => void) {
  const target = event.target instanceof HTMLElement ? event.target : null
  if (target && typeof target.focus === 'function') {
    target.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'smooth' })
    target.focus()
  }
  setStatus(i18n.t('messages.fixInvalidFields'))
}

function resolveSelectedTraceId(current: number | null, traces: RequestTrace[]): number | null {
  if (!current) {
    return null
  }
  return traces.some((trace) => trace.id === current) ? current : null
}

function providerMatches(provider: ProviderView, query: string, filter: FilterState): boolean {
  if (filter === 'enabled' && provider.disabled) {
    return false
  }
  if (filter === 'disabled' && !provider.disabled) {
    return false
  }
  if (!query) {
    return true
  }
	const haystack = [provider.id, provider.name || '', ...(provider.baseUrls || [provider.baseUrl]), providerAllModels(provider).join(' ')]
    .join(' ')
    .toLowerCase()
  return haystack.includes(query)
}

function aliasMatches(alias: AliasView, query: string, providers: ProviderView[] = []): boolean {
  if (!query) {
    return true
  }
  const targets = alias.targets.map((target) => `${target.provider} ${providerDisplayLabel(target.provider, providers)} ${target.model}`).join(' ')
  const haystack = [alias.alias, alias.displayName || '', targets].join(' ').toLowerCase()
  return haystack.includes(query)
}

