  async function openLifecycleImpact(
    kind: LifecycleImpactKind,
    subject: string,
    operation: LifecycleOperation,
    pendingGroupUpdate?: LifecyclePendingGroupUpdate,
  ) {
    setLifecycleImpact({
      kind,
      subject,
      operation,
      revision: '',
      plan: null,
      selections: {},
      loading: true,
      executing: false,
      outcome: null,
      executeResult: null,
      pendingGroupUpdate,
    })
    await loadLifecycleImpactPreview(kind, subject, operation, {}, pendingGroupUpdate)
  }

  async function loadLifecycleImpactPreview(
    kind: LifecycleImpactKind,
    subject: string,
    operation: LifecycleOperation,
    selectionsMap: Record<string, LifecycleSelectionEntry>,
    pendingGroupUpdate?: LifecyclePendingGroupUpdate,
  ) {
    setLifecycleImpact((current) =>
      current
        ? {
            ...current,
            kind,
            subject,
            operation,
            loading: true,
            executing: false,
            outcome: null,
            pendingGroupUpdate: pendingGroupUpdate ?? current.pendingGroupUpdate,
          }
        : {
            kind,
            subject,
            operation,
            revision: '',
            plan: null,
            selections: selectionsMap,
            loading: true,
            executing: false,
            outcome: null,
            executeResult: null,
            pendingGroupUpdate,
          },
    )
    try {
      const revView = await getConfigRevision()
      const revision = revView.revision
      const envelope = await previewLifecycleEnvelope({
        revision,
        operation,
        selections: lifecycleSelectionsFromState(selectionsMap),
      })
      if (!envelope.ok || !envelope.data) {
        setLifecycleImpact((current) =>
          current
            ? {
                ...current,
                revision,
                loading: false,
                plan: envelope.data || null,
                outcome: envelope.outcome,
              }
            : current,
        )
        if (envelope.outcome?.code === 'revision_conflict' || envelope.outcome?.code === 'preparation_stale') {
          setProviderStatus(outcomeMessage(envelope.outcome.code))
          setAliasStatus(outcomeMessage(envelope.outcome.code))
          closeLifecycleImpact()
          await refreshAll()
        }
        return
      }
      const plan = envelope.data
      setLifecycleImpact((current) => ({
        kind,
        subject,
        operation,
        revision,
        plan,
        selections: defaultLifecycleSelections(plan.choices, selectionsMap, providers),
        loading: false,
        executing: false,
        outcome: envelope.outcome,
        executeResult: null,
        pendingGroupUpdate: pendingGroupUpdate ?? current?.pendingGroupUpdate,
      }))
    } catch (error) {
      const message = formatError(error)
      setLifecycleImpact((current) =>
        current
          ? {
              ...current,
              loading: false,
              outcome:
                error instanceof TransportError
                  ? error.outcome
                  : { code: 'internal_error', params: {}, retryable: false },
            }
          : current,
      )
      if (error instanceof TransportError && (error.outcome.code === 'revision_conflict' || error.outcome.code === 'preparation_stale')) {
        setProviderStatus(message)
        setAliasStatus(message)
        closeLifecycleImpact()
        await refreshAll()
      }
    }
  }

  async function onLifecycleChoiceChange(choiceId: string, optionId: string) {
    const current = lifecycleImpact
    if (!current || current.loading || current.executing) {
      return
    }
    const choice = (current.plan?.choices || []).find((item) => item.id === choiceId)
    const params = choice ? defaultParamsForLifecycleOption(optionId, choice, providers) : undefined
    const selections = {
      ...current.selections,
      [choiceId]: { optionId, params },
    }
    await loadLifecycleImpactPreview(current.kind, current.subject, current.operation, selections)
  }

  async function onLifecycleChoiceParamChange(choiceId: string, patch: Record<string, unknown>) {
    const current = lifecycleImpact
    if (!current || current.loading || current.executing) {
      return
    }
    const existing = current.selections[choiceId] || { optionId: '' }
    if (!existing.optionId) {
      return
    }
    const selections = {
      ...current.selections,
      [choiceId]: {
        optionId: existing.optionId,
        params: { ...(existing.params || {}), ...patch },
      },
    }
    await loadLifecycleImpactPreview(current.kind, current.subject, current.operation, selections)
  }

  async function onExecuteLifecycleImpact() {
    const current = lifecycleImpact
    if (!current?.plan?.executable || current.loading || current.executing) {
      return
    }
    // group.id_change with pending fields: atomic UpdateProviderGroup (rename+fields via backend lifecycle).
    // Pure lifecycle execute still requires planToken for other kinds.
    if (current.kind !== 'group-id-change' || !current.pendingGroupUpdate) {
      if (!current.plan.planToken) {
        return
      }
    }
    setLifecycleImpact({ ...current, executing: true, outcome: null })
    const statusSetter =
      current.kind === 'alias-remove'
        ? setAliasStatus
        : current.kind === 'group-remove' || current.kind === 'group-id-change'
          ? setProviderGroupStatus
          : setProviderStatus
    statusSetter(
      current.kind === 'provider-remove'
        ? i18n.t('providers.statusDeleting', { id: current.subject })
        : current.kind === 'alias-remove'
          ? i18n.t('aliases.statusDeleting', { alias: current.subject })
          : current.kind === 'group-id-change'
            ? t(groupKey.statusSaving)
            : t(groupKey.statusDeleting),
    )
    try {
      if (current.kind === 'group-id-change' && current.pendingGroupUpdate) {
        const pending = current.pendingGroupUpdate
        try {
          // Must forward preview-collected lifecycle selections; backend PlanGroupIDChange
          // requires them when choices exist (same contract as delete).
          const updated = await updateProviderGroup({
            providerId: pending.providerId,
            groupId: pending.oldGroupId,
            group: pending.group,
            selections: lifecycleSelectionsFromState(current.selections),
            expectedRevision: current.plan.baseRevision,
          })
          closeLifecycleImpact()
          await reloadProviderGroups(pending.providerId, updated.id)
          setProviderGroupStatus(t(groupKey.statusSaved))
          await refreshAll()
        } catch (error) {
          setLifecycleImpact((state) =>
            state
              ? {
                  ...state,
                  executing: false,
                  outcome:
                    error instanceof TransportError
                      ? error.outcome
                      : { code: 'internal_error', params: {}, retryable: false },
                }
              : state,
          )
          statusSetter(`${t(groupKey.errorSave)}: ${formatError(error)}`)
          if (error instanceof TransportError && (error.outcome.code === 'revision_conflict' || error.outcome.code === 'preparation_stale')) {
            closeLifecycleImpact()
            await refreshAll()
          }
        }
        return
      }

      const envelope = await executeLifecycleEnvelope({
        revision: current.revision,
        planToken: current.plan.planToken || '',
        operation: current.operation,
        selections: lifecycleSelectionsFromState(current.selections),
      })
      if (!envelope.ok) {
        const code = envelope.outcome?.code || 'internal_error'
        setLifecycleImpact((state) =>
          state
            ? {
                ...state,
                executing: false,
                outcome: envelope.outcome,
                executeResult: envelope.data || null,
                plan: envelope.data?.plan || state.plan,
              }
            : state,
        )
        if (code === 'revision_conflict' || code === 'preparation_stale') {
          statusSetter(outcomeMessage(code))
          closeLifecycleImpact()
          await refreshAll()
          return
        }
        if (code === 'runtime_apply_failed') {
          statusSetter(i18n.t('lifecycle.applyFailed', { state: envelope.data?.runtimeState || code }))
          closeLifecycleImpact()
          if (current.kind === 'provider-remove' && selectedProviderId === current.subject) {
            setSelectedProviderId(null)
            resetProviderForm()
            setProviderDetailMode('empty')
          }
          if (current.kind === 'alias-remove' && selectedAliasId === current.subject) {
            setSelectedAliasId(null)
            resetAliasForm()
            setAliasDetailMode('empty')
          }
          if (current.kind === 'group-remove' && selectedProviderGroupId === current.subject) {
            setSelectedProviderGroupId('')
            setProviderGroupForm(emptyProviderGroupForm)
          }
          await refreshAll()
          return
        }
        statusSetter(outcomeMessage(code))
        return
      }
      const result = envelope.data
      const summary =
        result?.pendingRestart
          ? i18n.t('lifecycle.restartPending')
          : i18n.t('lifecycle.executed', { state: result?.runtimeState || 'ok' })
      closeLifecycleImpact()
      if (current.kind === 'provider-remove') {
        if (selectedProviderId === current.subject) {
          setSelectedProviderId(null)
          resetProviderForm()
          setProviderDetailMode('empty')
        }
        setProviderStatus(summary)
      } else if (current.kind === 'alias-remove') {
        if (selectedAliasId === current.subject) {
          setSelectedAliasId(null)
          resetAliasForm()
          setAliasDetailMode('empty')
        }
        setAliasStatus(summary)
      } else {
        if (selectedProviderGroupId === current.subject) {
          setSelectedProviderGroupId('')
          setProviderGroupForm(emptyProviderGroupForm)
        }
        setProviderGroupStatus(summary)
      }
      await refreshAll()
    } catch (error) {
      statusSetter(formatError(error))
      setLifecycleImpact((state) =>
        state
          ? {
              ...state,
              executing: false,
              outcome:
                error instanceof TransportError
                  ? error.outcome
                  : { code: 'internal_error', params: {}, retryable: false },
              executeResult: error instanceof TransportError ? (error.data as LifecycleExecuteResult | undefined) || null : null,
            }
          : state,
      )
      if (error instanceof TransportError && (error.outcome.code === 'revision_conflict' || error.outcome.code === 'preparation_stale')) {
        closeLifecycleImpact()
        await refreshAll()
      }
    }
  }

  async function onTargetRepairAction(alias: AliasView, target: AliasTargetView, action: string) {
    const targetGroup = (target.group || '').trim() || 'default'
    const providerLabel = providerDisplayLabel(target.provider, providers)
    setAliasStatus(i18n.t('aliases.statusRepairing', { action, provider: providerLabel, model: target.model }))
    try {
      switch (action) {
        case 'enable_target':
          await setAliasTargetState({
            alias: alias.alias,
            provider: target.provider,
            group: targetGroup,
            model: target.model,
            disabled: false,
          })
          break
        case 'remove_target':
          await unbindAliasTarget({
            alias: alias.alias,
            provider: target.provider,
            group: targetGroup,
            model: target.model,
            disabled: !target.enabled,
          })
          break
        case 'enable_provider':
          await setProviderState({ id: target.provider, disabled: false })
          break
        case 'refresh_catalog':
          // Non-default groups must refresh the exact group; empty maps only to default.
          if (targetGroup && targetGroup !== 'default') {
            await refreshProviderGroupModels({ providerId: target.provider, groupId: targetGroup })
          } else {
            await refreshProviderModels({ id: target.provider, group: targetGroup || 'default' })
          }
          break
        case 'delete_alias':
          await openLifecycleImpact('alias-remove', alias.alias, aliasRemoveOperation(alias.alias))
          return
        case 'rebind_target':
          setTargetForm({
            alias: alias.alias,
            provider: target.provider,
            group: targetGroup,
            model: target.model,
            disabled: !target.enabled,
          })
          setActiveModal('alias-target')
          setAliasStatus(i18n.t('aliases.statusRebindHint', { provider: providerLabel, model: target.model }))
          return
        default:
          setAliasStatus(i18n.t('aliases.repairUnsupported', { action }))
          return
      }
      setAliasStatus(i18n.t('aliases.statusRepaired', { action, provider: providerLabel, model: target.model }))
      await refreshAll()
    } catch (error) {
      setAliasStatus(formatError(error))
    }
  }

